 Item parse(JSONObject o)throws Exception {String title=o.getString("title"),text=o.getString("text"),type=o.getString("type");if(title.trim().isEmpty()||(text.trim().isEmpty()&&o.optJSONArray("files")==null)||title.length()>150||text.length()>200000||!(type.equals("prompt")||type.equals("block")))throw new Exception("Ungültiger Eintrag");Item i=new Item(title,text,type);i.cloud=o.optBoolean("cloud",false);i.cloudOwner=o.optString("cloudOwner","");if(!i.cloudOwner.matches("[a-f0-9]{64}"))i.cloud=false;i.project=o.optString("project","");if(i.project.length()>150)throw new IOException("Projektname zu lang");i.id=o.optString("id",i.id);i.createdAt=o.optLong("createdAt",0);i.updatedAt=o.optLong("updatedAt",i.createdAt);i.star=o.optBoolean("star",false);i.archived=o.optBoolean("archived",false);i.files=readAtt(o.optJSONArray("files"));if(text.trim().isEmpty()&&i.files.isEmpty())throw new IOException("Leerer Eintrag");return i;}
 JSONArray data()throws JSONException{JSONArray a=new JSONArray();for(Item i:items)a.put(i.json());return a;}
