 void render(){if(rows==null)return;prompts.setTextColor(tab.equals("prompt")?ACCENT:MUTED);blocks.setTextColor(tab.equals("block")?ACCENT:MUTED);stars.setText(fav?"★":"☆");stars.setTextColor(fav?ACCENT:MUTED);rows.removeAllViews();String q=search.getText().toString();int n=0;for(Item i:sortedItems()){if(i.archived||(!q.trim().isEmpty()?!matches(i,q):!i.type.equals(tab))||(fav&&!i.star))continue;n++;rows.addView(itemCard(i,false));}if(n==0)rows.addView(label("Keine aktiven Einträge gefunden. Alle Einträge stehen unter Liste.",16,MUTED));renderOverview();renderProject();}
 ArrayList<Item> sortedItems(){ArrayList<Item> sorted=new ArrayList<>(items);Collections.sort(sorted,(a,b)->Boolean.compare(b.star,a.star));return sorted;}
