 if(!overview){LinearLayout tools=line();addCompact(tools,button("Kopieren",()->copyText(i.title,i.text)));addCompact(tools,button("Einfügen",()->insertItem(i)));addCompact(tools,button(i.type.equals("block")?"→ Prompt":"→ Baustein",()->convertItem(i)));addCompact(tools,button("Erledigt",()->setArchived(i,true)));card.addView(scrollRow(tools));}
