 void showOverview(){if(overviewDialog!=null)return;LinearLayout body=col();body.setPadding(dp(12),dp(8),dp(12),dp(8));body.setBackgroundColor(BG);body.addView(label("Liste · Prompts, Bausteine und Erledigte",18,INK));body.addView(label("Antippen öffnet · Halten zeigt das Menü · Zurück zur Hauptseite",11,MUTED));overviewSearch=input("Liste durchsuchen · Wort / Datum");overviewSearch.setSingleLine(true);body.addView(overviewSearch,new LinearLayout.LayoutParams(-1,dp(48)));ScrollView scroll=new ScrollView(this);overviewRows=col();scroll.addView(overviewRows);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));overviewSearch.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){renderOverview();}public void afterTextChanged(Editable e){}});overviewDialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar);overviewDialog.setContentView(body);overviewDialog.setOnDismissListener(d->{overviewDialog=null;overviewRows=null;overviewSearch=null;});overviewDialog.show();overviewDialog.getWindow().setLayout(-1,-1);KeyboardLayout.install(overviewDialog.getWindow(),body);renderOverview();}
 void renderOverview(){if(overviewRows==null)return;overviewRows.removeAllViews();String q=overviewSearch.getText().toString();for(Item i:sortedItems())if(q.trim().isEmpty()||matches(i,q))overviewRows.addView(itemCard(i,true));if(overviewRows.getChildCount()==0)overviewRows.addView(label("Keine Einträge gefunden.",16,MUTED));}
 void insert(String s){if(handedOver){newPrompt();if(handedOver)return;}int a=Math.max(0,editor.getSelectionStart()),b=Math.max(0,editor.getSelectionEnd());int lo=Math.min(a,b),hi=Math.max(a,b);String before=editor.getText().toString();String prefix=(lo>0&&!Character.isWhitespace(before.charAt(lo-1)))?"\n\n":"";String suffix=(hi<before.length()&&!Character.isWhitespace(before.charAt(hi)))?"\n\n":"";editor.getText().replace(lo,hi,prefix+s+suffix);editor.setSelection(lo+prefix.length()+s.length());showDraft();toast("Eingefügt");}
 void undo(){if(busy)return;setHandedOver(false);String old=last;ArrayList<Att> oldFiles=lastFiles;restoring=true;last=editor.getText().toString();lastFiles=new ArrayList<>(draftFiles);editor.setText(old);draftFiles=new ArrayList<>(oldFiles);editor.setSelection(editor.length());restoring=false;draftChanged();}
 void clear(){if(busy){toast("Bitte Dateiübertragung abwarten");return;}setHandedOver(false);if(editor.length()>0||!draftFiles.isEmpty()){last=editor.getText().toString();lastFiles=new ArrayList<>(draftFiles);restoring=true;editor.setText("");draftFiles.clear();restoring=false;draftChanged();}}
 void showDraft(){editPane.setVisibility(View.VISIBLE);if(foldButton!=null)foldButton.setText("Editor ▴");}
 void copyText(String label,String value){if(value.isEmpty()){toast("Dieser Text ist noch leer");return;}((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText(label,value));toast("Text kopiert · Inhalt bleibt erhalten");}
 void copy(){copyText("Prompt",editor.getText().toString());}
 void share(){shareContent(editor.getText().toString(),new ArrayList<>(draftFiles));}
 void shareContent(String value,ArrayList<Att> files){
  if(busy)return;if(value.isEmpty()&&files.isEmpty()){toast("Text und Anhänge sind noch leer");return;}
  try{
   Intent i=new Intent(files.size()>1?Intent.ACTION_SEND_MULTIPLE:Intent.ACTION_SEND);i.putExtra(Intent.EXTRA_TEXT,value);i.setType("text/plain");
   if(!files.isEmpty()){
    ArrayList<android.net.Uri> uris=new ArrayList<>();String mime=files.get(0).mime;
    for(Att a:files){if(!file(a).isFile())throw new IOException("Anhang fehlt: "+a.name);uris.add(uri(a));if(!mime.equals(a.mime))mime="*/*";}
    i.setType(mime);if(uris.size()==1)i.putExtra(Intent.EXTRA_STREAM,uris.get(0));else i.putParcelableArrayListExtra(Intent.EXTRA_STREAM,uris);
    ClipData clip=ClipData.newRawUri("Anhänge",uris.get(0));for(int j=1;j<uris.size();j++)clip.addItem(new ClipData.Item(uris.get(j)));i.setClipData(clip);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
   }
   startActivity(Intent.createChooser(i,"Prompt und Anhänge teilen"));
  }catch(Exception e){error(e);}
 }
 void saveDraft(){if(busy)return;if(editor.getText().toString().trim().isEmpty()&&draftFiles.isEmpty()){toast("Schreibe einen Prompt oder füge Anhänge hinzu");return;}Item i=new Item("",editor.getText().toString(),"prompt");i.files=new ArrayList<>(draftFiles);edit(i,false);}
 void setArchived(Item i,boolean archived){boolean previous=i.archived;i.archived=archived;if(!persist()){i.archived=previous;return;}render();toast(archived?"Als erledigt abgelegt":"Zurück in der Sammlung");}
 void itemMenu(Item i){new AlertDialog.Builder(this).setTitle(i.title).setItems(new String[]{"Einfügen","Bearbeiten",i.star?"Favorit entfernen":"Als Favorit markieren",i.archived?"Zurückholen":"Erledigt","Löschen","Tokensparer: auf Deutsch holen","Kopieren",i.type.equals("block")?"In Prompt umwandeln":"In Baustein umwandeln","Projekt zuordnen"},(d,w)->{if(w==8)chooseProject(i);if(w==6)copyText(i.title,i.text);if(w==7)convertItem(i);if(w==5)translateText(i.text,false,new ArrayList<>(i.files));if(w==0){if(overviewDialog!=null)overviewDialog.dismiss();insertItem(i);}if(w==1)edit(i);if(w==2){i.star=!i.star;persist();render();}if(w==3)setArchived(i,!i.archived);if(w==4)new AlertDialog.Builder(this).setTitle("Eintrag endgültig löschen?").setMessage(i.title+"\n\nZum Aufbewahren kannst du den Eintrag als erledigt ablegen.").setNegativeButton("Abbrechen",null).setPositiveButton("Löschen",(x,y)->{items.remove(i);persist();render();}).show();}).show();}
