 void edit(Item original,boolean clearDraftAfterSave){boolean existing=original!=null&&items.contains(original);ArrayList<Att> editingFiles=original==null?new ArrayList<>():new ArrayList<>(original.files);LinearLayout form=col();form.setPadding(dp(20),dp(8),dp(20),dp(8));EditText title=input("Titel");title.setSingleLine(true);title.setFilters(new InputFilter[]{new InputFilter.LengthFilter(150)});EditText text=input("Text deines Eintrags");text.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);text.setGravity(Gravity.TOP);text.setMinLines(5);text.setMaxLines(10);text.setFilters(new InputFilter[]{new InputFilter.LengthFilter(200000)});Spinner kind=new Spinner(this);kind.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Prompt","Textbaustein"}));if(original!=null){title.setText(original.title);text.setText(original.text);kind.setSelection(original.type.equals("block")?1:0);}else kind.setSelection(tab.equals("block")?1:0);form.addView(title);form.addView(kind);Spinner storage=new Spinner(this);storage.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Nur auf diesem Gerät","Mit meinem Google Drive synchronisieren"}));storage.setSelection(!DriveSync.autoOwner(this).isEmpty()?1:original!=null&&original.cloud?1:0);storage.setEnabled(DriveSync.autoOwner(this).isEmpty());form.addView(storage);form.addView(text);Button fileButton=button("＋ Anhänge · "+editingFiles.size(),()->{});fileButton.setOnClickListener(v->attachments(editingFiles,()->fileButton.setText("＋ Anhänge · "+editingFiles.size())));form.addView(fileButton);ScrollView scroll=new ScrollView(this);scroll.addView(form);AlertDialog dlg=new AlertDialog.Builder(this).setTitle(existing?"Eintrag bearbeiten":"In Sammlung speichern").setView(scroll).setNegativeButton("Abbrechen",null).setPositiveButton("Speichern",null).create();dlg.setOnShowListener(v->dlg.getButton(-1).setOnClickListener(b->{String t=title.getText().toString().trim(),x=text.getText().toString();if(t.isEmpty()){title.setError("Bitte einen Titel eingeben");return;}if(x.trim().isEmpty()&&editingFiles.isEmpty()){text.setError("Bitte Text eingeben");return;}String type=kind.getSelectedItemPosition()==1?"block":"prompt";boolean cloud=storage.getSelectedItemPosition()==1;JSONObject auth=DriveSync.connection(this);if(cloud&&(auth==null||!auth.has("account")||auth.optBoolean("disconnectPending"))){toast("Bitte zuerst Mein Google Drive im Menü verbinden");return;}saveItem(existing?original:null,t,x,type,editingFiles,cloud,cloud?auth.optString("account"):original==null?"":original.cloudOwner,()->{if(clearDraftAfterSave)clear();dlg.dismiss();toast("Gespeichert");});}));dlg.show();}
 String normalized(String value){return java.text.Normalizer.normalize(value.trim().replaceAll("\\s+"," "),java.text.Normalizer.Form.NFKC).toLowerCase(Locale.ROOT);}
