 String dateLabel(Item item){return item.updatedAt==0?"Datum unbekannt":new java.text.SimpleDateFormat("dd.MM.yyyy",Locale.GERMANY).format(new Date(item.updatedAt));}
 boolean matches(Item item,String query){String hay=(item.project+" "+item.title+" "+item.text+" "+dateLabel(item)+" "+(item.createdAt==0?"":new java.text.SimpleDateFormat("yyyy-MM-dd dd.MM.yyyy",Locale.GERMANY).format(new Date(item.createdAt)))+" "+(item.updatedAt==0?"":new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date(item.updatedAt)))).toLowerCase(Locale.ROOT);for(String word:query.trim().toLowerCase(Locale.ROOT).split("\\s+"))if(!hay.contains(word))return false;return true;}
 void mergeImport(ArrayList<Item> incoming,Runnable success){try{ArrayList<Item> next=new ArrayList<>();for(Item it:items)next.add(parse(it.json()));ArrayList<String> conflicts=new ArrayList<>();for(Item it:incoming){int found=-1;for(int n=0;n<next.size();n++)if(normalized(next.get(n).title).equals(normalized(it.title))){found=n;break;}Item copy=parse(it.json());if(found<0){copy.id=UUID.randomUUID().toString();next.add(copy);}else{Item old=next.get(found);if(old.text.equals(copy.text)&&old.type.equals(copy.type)&&old.project.equals(copy.project)&&attJson(old.files).toString().equals(attJson(copy.files).toString()))continue;conflicts.add(old.title);copy.id=old.id;next.set(found,copy);}}Runnable commit=()->{ArrayList<Item> before=new ArrayList<>(items);items.clear();items.addAll(next);if(!persist()){items.clear();items.addAll(before);return;}render();toast("Import abgeschlossen");success.run();};if(conflicts.isEmpty()){commit.run();return;}new AlertDialog.Builder(this).setTitle("Einträge scheinen bereits zu existieren").setMessage(conflicts.size()+" Namenskonflikte, zum Beispiel: "+conflicts.get(0)+". Gleichnamige Einträge werden ersetzt; bei mehreren gleichnamigen Einträgen in der Sicherung gilt der letzte.").setNegativeButton("Abbrechen",null).setPositiveButton("Überschreiben",(d,w)->new AlertDialog.Builder(this).setTitle("Wirklich überschreiben?").setMessage("Die genannten Namenskonflikte werden überschrieben. Abbrechen lässt die Sammlung unverändert.").setNegativeButton("Abbrechen",null).setPositiveButton("Wirklich überschreiben",(x,y)->commit.run()).show()).show();}catch(Exception e){error(e);}}
 void driveBackup(){new AlertDialog.Builder(this).setTitle("In Google Drive sichern").setMessage("Die vollständige ZIP-Sicherung wird direkt an Google Drive übergeben. Wähle im Drive-Fenster das Konto und den Ordner und tippe dort auf Speichern. Google Drive muss installiert und angemeldet sein. Die App bestätigt nur die Übergabe; den Uploadstatus zeigt Drive.").setNegativeButton("Abbrechen",null).setPositiveButton("Drive-Konto wählen",(d,w)->sendDriveBackup()).show();}
 void sendDriveBackup(){try{JSONObject manifest=new JSONObject();manifest.put("format","promptwerk");manifest.put("version",3);manifest.put("items",data());manifest.put("draft",editor.getText().toString());manifest.put("draftFiles",attJson(draftFiles));manifest.put("ideas",new JSONObject(prefs.getString(ideasKey(),"{}")));manifest.put("parkedDrafts",new JSONArray(prefs.getString(parkedKey(),"[]")));ArrayList<Att> all=backupFiles();work(()->{File dir=new File(getCacheDir(),"drive-backups");dir.mkdirs();File target=new File(dir,UUID.randomUUID()+".zip");buildBackup(target,manifest,all);runOnUiThread(()->{android.net.Uri uri=new android.net.Uri.Builder().scheme("content").authority(getPackageName()+".attachments").appendPath("backup").appendPath(target.getName()).appendQueryParameter("name","Promptwerk-Komplettsicherung-"+new java.text.SimpleDateFormat("yyyy-MM-dd-HHmmss",Locale.ROOT).format(new Date())+".zip").build();Intent intent=driveIntent(uri);try{startActivity(intent);toast("An Drive übergeben · dort Konto wählen und speichern");}catch(ActivityNotFoundException e){toast("Google Drive fehlt oder unterstützt diese Übergabe nicht. Bitte Drive installieren oder Sicherung exportieren wählen.");}});});}catch(Exception e){error(e);}}
 Intent driveIntent(android.net.Uri uri){Intent intent=new Intent(Intent.ACTION_SEND);intent.setPackage("com.google.android.apps.docs");intent.setType("application/zip");intent.putExtra(Intent.EXTRA_STREAM,uri);intent.setClipData(ClipData.newRawUri("Promptwerk-Sicherung",uri));intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);return intent;}
 ArrayList<Att> backupFiles()throws Exception{ArrayList<Att> all=new ArrayList<>(draftFiles);for(Item it:items)all.addAll(it.files);JSONArray parked=new JSONArray(prefs.getString(parkedKey(),"[]"));for(int n=0;n<parked.length();n++)all.addAll(readAtt(parked.getJSONObject(n).optJSONArray("files")));return all;}
 void addTransferActions(LinearLayout parent){
 LinearLayout row=line();Button transfer=button("Prompt übergeben",()->handover());Button next=button("Neuer Prompt",()->newPrompt());Button resume=button("Weiterbearbeiten",()->setHandedOver(false));addCompact(row,transfer);addCompact(row,next);addCompact(row,resume);if(parent==editPane)transfer.setVisibility(View.GONE);parent.addView(row);transferRows.add(row);updateTransferActions();}
 void updateTransferActions(){for(View view:transferRows){LinearLayout row=(LinearLayout)view;row.getChildAt(0).setVisibility(handedOver||row.getParent()==editPane?View.GONE:View.VISIBLE);row.setVisibility(row.getParent()==editPane&&!handedOver?View.GONE:View.VISIBLE);row.getChildAt(1).setVisibility(handedOver?View.VISIBLE:View.GONE);row.getChildAt(2).setVisibility(handedOver?View.VISIBLE:View.GONE);}}
 void setHandedOver(boolean value){handedOver=value;if(!value&&reading)setReading(false);prefs.edit().putBoolean("handedOver",value).apply();editor.setEnabled(!value);if(value){editor.clearFocus();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(editor.getWindowToken(),0);}updateTransferActions();counter();}
 void newPrompt(){if(busy)return;try{parkDraft();clear();showDraft();editor.requestFocus();}catch(Exception e){error(e);}}
 void parkDraft(){if(editor.length()==0&&draftFiles.isEmpty())return;try{JSONArray parked=new JSONArray(prefs.getString(parkedKey(),"[]"));JSONObject o=new JSONObject();o.put("text",editor.getText().toString());o.put("files",attJson(draftFiles));o.put("time",System.currentTimeMillis());parked.put(o);if(!prefs.edit().putString(parkedKey(),parked.toString()).commit())throw new IOException("Entwurf konnte nicht geparkt werden");DriveSync.capture(this,data());}catch(Exception e){throw new IllegalStateException(e);}}
 void newEntry(){if(entryWindow==null)entryWindow=new EntryWindow(this,new Item("","",tab));}
 void parkedDrafts(){try{JSONArray parked=new JSONArray(prefs.getString(parkedKey(),"[]"));if(parked.length()==0){toast("Keine geparkten Entwürfe");return;}String[] labels=new String[parked.length()];for(int i=0;i<labels.length;i++)labels[i]=parked.getJSONObject(i).optString("text","Dateientwurf").replace('\n',' ');new AlertDialog.Builder(this).setTitle("Geparkte Entwürfe · separat öffnen").setItems(labels,(d,w)->{try{JSONObject o=parked.getJSONObject(w);Item it=new Item("",o.getString("text"),"prompt");it.files=readAtt(o.optJSONArray("files"));edit(it,false);}catch(Exception e){error(e);}}).setNegativeButton("Schließen",null).show();}catch(Exception e){error(e);}}
 void convertItem(Item item){String previous=item.type;long before=item.updatedAt;item.type=previous.equals("block")?"prompt":"block";item.updatedAt=System.currentTimeMillis();if(!persist()){item.type=previous;item.updatedAt=before;return;}tab=item.type;render();toast(item.type.equals("block")?"In Baustein umgewandelt":"In Prompt umgewandelt");}
