 void handover(){if(editor.length()==0){toast("Dieser Text ist noch leer");return;}try{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Prompt",editor.getText().toString()));setHandedOver(true);toast(draftFiles.isEmpty()?"Kopiert · Editor geschützt":"Text kopiert · Anhänge bleiben zum Teilen erhalten");}catch(Exception e){error(e);}}
 void checkUpdates(){if(updateChecking){toast("Update-Prüfung läuft bereits");return;}updateChecking=true;toast("Suche nach Updates …");new Thread(()->{try{UpdateInfo info=UpdateInfo.fetch();runOnUiThread(()->{if(isFinishing()||isDestroyed())return;try{int current=getPackageManager().getPackageInfo(getPackageName(),0).versionCode;if(info.code<=current){new AlertDialog.Builder(this).setTitle("Auf dem neuesten Stand").setMessage("Promptwerk "+getPackageManager().getPackageInfo(getPackageName(),0).versionName+" ist aktuell.").setPositiveButton("OK",null).show();}else new AlertDialog.Builder(this).setTitle("Promptwerk "+info.version+" verfügbar").setMessage("Vor dem Update eine Sicherung exportieren. Anschließend die APK als Update installieren; die App nicht deinstallieren.").setNegativeButton("Später",null).setPositiveButton("Download öffnen",(d,w)->openWeb(info.url)).show();}catch(Exception e){error(e);}});}catch(Exception e){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setTitle("Update-Prüfung nicht möglich").setMessage("Bitte Internetverbindung prüfen und später erneut versuchen. Du kannst Promptwerk weiter offline verwenden.").setPositiveButton("OK",null).show();});}finally{updateChecking=false;}}).start();}
