 void menu(){new AlertDialog.Builder(this).setTitle("Promptwerk").setItems(new String[]{"+ Neuer Textbaustein","Sicherung exportieren","Sicherung importieren","Ausführliche Anleitung","Info & Impressum","Auf Updates prüfen","Alles auf GDrive speichern","Projektideen","Geparkte Entwürfe","Prompt automatisch optimieren","Liste","Projekte / TXT exportieren","Spracheingabe","Mein Google Drive / Sync"},(d,w)->{if(w==13)DriveSync.menu(this);if(w==12)dictate();if(w==11)showProjects();if(w==7)ideas();if(w==8)parkedDrafts();if(w==9)optimize(editor.getText().toString(),new ArrayList<>(draftFiles));if(w==6)driveBackup();if(w==5)checkUpdates();if(w==0){tab="block";render();newEntry();}if(w==1){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/zip");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"Promptwerk-Sicherung-"+new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date())+".zip");startActivityForResult(i,10);}if(w==2){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,11);}if(w==4)showInfo();if(w==10)showOverview();if(w==3)showManual();}).show();}
 @Override protected void onActivityResult(int req,int result,Intent intent){super.onActivityResult(req,result,intent);if(req==SpeechInput.REQUEST){speechInput.result(result,intent);return;}if(result!=RESULT_OK||intent==null)return;if(req==30){final String project=pendingProject;pendingProject=null;if(project!=null&&intent.getData()!=null)exportProject(intent.getData(),project);return;}if(req==20){java.util.ArrayList<android.net.Uri> uris=new java.util.ArrayList<>();if(intent.getClipData()!=null){for(int j=0;j<intent.getClipData().getItemCount();j++)uris.add(intent.getClipData().getItemAt(j).getUri());}else if(intent.getData()!=null)uris.add(intent.getData());ArrayList<Att> target=pickTarget==null?draftFiles:pickTarget;Runnable done=afterPick==null?()->draftChanged():afterPick;pickTarget=null;afterPick=null;work(()->{ArrayList<Att> combined=new ArrayList<>(target);for(android.net.Uri u:uris){combined.add(importFile(u));readAtt(attJson(combined));}runOnUiThread(()->{target.clear();target.addAll(combined);done.run();toast("Anhänge hinzugefügt");});});return;}if(intent.getData()==null)return;android.net.Uri u=intent.getData();if(req==10){try{JSONObject manifest=new JSONObject();manifest.put("format","promptwerk");manifest.put("version",3);manifest.put("items",data());manifest.put("ideas",new JSONObject(prefs.getString(ideasKey(),"{}")));manifest.put("parkedDrafts",new JSONArray(prefs.getString(parkedKey(),"[]")));manifest.put("draft",editor.getText().toString());manifest.put("draftFiles",attJson(draftFiles));ArrayList<Att> all=backupFiles();work(()->exportBackup(u,manifest,all));}catch(Exception e){error(e);}}if(req==11)work(()->importBackup(u));}
 File file(Att a){return new File(getFilesDir(),"attachments/"+a.key);}
 android.net.Uri uri(Att a){return new android.net.Uri.Builder().scheme("content").authority(getPackageName()+".attachments").appendPath(a.key).appendQueryParameter("name",a.name).appendQueryParameter("type",a.mime).build();}
 void error(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Nicht abgeschlossen").setMessage(e.getMessage()==null?"Die Datei konnte nicht verarbeitet werden.":e.getMessage()).setPositiveButton("OK",null).show());}
 interface Job{void run()throws Exception;}
 void work(Job job){if(busy){toast("Bitte laufende Dateiübertragung abwarten");return;}busy=true;ProgressDialog progress=new ProgressDialog(this);progress.setMessage("Dateien werden verarbeitet …");progress.setCancelable(false);progress.show();new Thread(()->{try{job.run();}catch(Exception e){error(e);}finally{runOnUiThread(()->{busy=false;if(!isFinishing())progress.dismiss();});}}).start();}
 String digest(File f)throws Exception{java.security.MessageDigest md=java.security.MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)md.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:md.digest())s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();}
 void pruneUnreferencedFiles(){HashSet<String> keep=DriveSync.referencedFiles(this);if(keep==null)return;try{JSONArray parked=new JSONArray(prefs.getString(parkedKey(),"[]"));for(int n=0;n<parked.length();n++)for(Att f:readAtt(parked.getJSONObject(n).optJSONArray("files")))keep.add(f.key);}catch(Exception e){return;}if(entryWindow!=null)for(Att a:entryWindow.files)keep.add(a.key);for(Item i:items)for(Att a:i.files)keep.add(a.key);for(Att a:draftFiles)keep.add(a.key);File[] stored=new File(getFilesDir(),"attachments").listFiles();if(stored!=null)for(File f:stored)if(AttachmentPolicy.validKey(f.getName())&&!keep.contains(f.getName()))f.delete();}
 void draftChanged(){try{if(!prefs.edit().putString("draftFiles",attJson(draftFiles).toString()).commit())throw new IOException("Entwurfsanhänge konnten nicht gespeichert werden.");}catch(Exception e){error(e);}if(attachButton!=null)attachButton.setText(draftFiles.isEmpty()?"＋ Anhang hinzufügen":"📎 Anhänge verwalten · "+draftFiles.size());}
 void insertItem(Item it){if(busy)return;if(handedOver)newPrompt();try{ArrayList<Att> joined=new ArrayList<>(draftFiles);for(Att a:it.files){boolean found=false;for(Att b:joined)if(a.key.equals(b.key)&&a.name.equals(b.name))found=true;if(!found)joined.add(a);}readAtt(attJson(joined));last=editor.getText().toString();lastFiles=new ArrayList<>(draftFiles);restoring=true;insert(it.text);restoring=false;draftFiles=joined;draftChanged();}catch(Exception e){restoring=false;error(e);}}

 void copyAttachment(Att attachment){try{File source=file(attachment);if(!source.isFile()||source.length()!=attachment.size)throw new IOException("Anhang fehlt oder ist beschädigt");android.content.ClipboardManager clipboard=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newUri(getContentResolver(),attachment.name,uri(attachment)));toast("Anhang kopiert · in einer passenden App einfügen");}catch(Exception e){error(e);}}
 ArrayList<String> projectNames(){TreeSet<String> names=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);for(Item i:items)if(!i.archived&&i.type.equals("prompt")&&!i.project.isEmpty())names.add(i.project);return new ArrayList<>(names);}
 void assignProject(Item item,String name){if(item.archived||!item.type.equals("prompt")){toast("Nur aktive Prompts können einem Projekt zugeordnet werden");return;}String value=name.trim().replaceAll("\\s+"," ");if(value.length()>150){toast("Projektname: höchstens 150 Zeichen");return;}for(String known:projectNames())if(normalized(known).equals(normalized(value))){value=known;break;}String old=item.project;long time=item.updatedAt;item.project=value;item.updatedAt=System.currentTimeMillis();if(!persist()){item.project=old;item.updatedAt=time;return;}render();toast(value.isEmpty()?"Projektzuordnung entfernt":"Projekt: "+value);}
 void chooseProject(Item item){if(item.archived||!item.type.equals("prompt")){toast("Nur aktive Prompts können einem Projekt zugeordnet werden");return;}ArrayList<String> names=projectNames();ArrayList<String> labels=new ArrayList<>();labels.add("+ Neues Projekt");labels.add("Ohne Projekt");labels.addAll(names);new AlertDialog.Builder(this).setTitle("Projekt für „"+item.title+"“").setItems(labels.toArray(new String[0]),(d,w)->{if(w==0){EditText name=input("Projektname");name.setSingleLine(true);name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(150)});AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Neues Projekt").setView(name).setNegativeButton("Abbrechen",null).setPositiveButton("Zuordnen",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{if(name.getText().toString().trim().isEmpty()){name.setError("Bitte Projektname eingeben");return;}assignProject(item,name.getText().toString());dialog.dismiss();}));dialog.show();}else assignProject(item,w==1?"":names.get(w-2));}).setNegativeButton("Abbrechen",null).show();}
 void showProjects(){ArrayList<String> names=projectNames();if(names.isEmpty()){new AlertDialog.Builder(this).setTitle("Projekte").setMessage("Tippe an einem Eintrag auf Projekt, um ihn zuzuordnen oder ein Projekt anzulegen.").setPositiveButton("OK",null).show();return;}new AlertDialog.Builder(this).setTitle("Projekte · TXT exportieren").setItems(names.toArray(new String[0]),(d,w)->showProject(names.get(w))).setNegativeButton("Schließen",null).show();}
 void showProject(String name){if(projectDialog!=null)projectDialog.dismiss();openProject=name;LinearLayout body=col();body.setPadding(dp(12),dp(8),dp(12),dp(8));body.setBackgroundColor(BG);body.addView(label(name,20,INK));body.addView(button("Ganzes Projekt als TXT exportieren",()->requestProjectExport(name)));ScrollView scroll=new ScrollView(this);projectRows=col();scroll.addView(projectRows);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));projectDialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar);projectDialog.setContentView(body);projectDialog.setOnDismissListener(d->{projectDialog=null;projectRows=null;openProject=null;});projectDialog.show();projectDialog.getWindow().setLayout(-1,-1);KeyboardLayout.install(projectDialog.getWindow(),body);renderProject();}
 void renderProject(){if(projectRows==null)return;projectRows.removeAllViews();for(Item item:items)if(!item.archived&&item.type.equals("prompt")&&item.project.equals(openProject))projectRows.addView(itemCard(item,false));if(projectRows.getChildCount()==0)projectRows.addView(label("Keine aktiven Prompts in diesem Projekt.",16,MUTED));}
 void requestProjectExport(String name){new AlertDialog.Builder(this).setTitle("Projekt als TXT").setMessage("Enthält ausschließlich aktive Prompts dieses Projekts als nummerierte Arbeitsaufträge. Bausteine und erledigte Prompts sind ausgeschlossen. TXT-Anhänge stehen als Text, Bilder/PDF als Base64 im Dokument. Nicht jede KI kann diese Dateidaten lesen. Der Hinweis zur nur vorübergehenden Nutzung ist keine technische Speichersperre; nutze bei der Ziel-KI einen temporären Chat und passende Datenschutzeinstellungen.").setNegativeButton("Abbrechen",null).setPositiveButton("TXT speichern",(d,w)->{pendingProject=name;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("text/plain");intent.putExtra(Intent.EXTRA_TITLE,"Promptwerk-"+name.replaceAll("[^\\p{L}\\p{N}._ -]","_")+".txt");startActivityForResult(intent,30);}).show();}
 void exportProject(android.net.Uri destination,String name){try{ArrayList<Item> snapshot=new ArrayList<>();for(Item item:items)if(!item.archived&&item.type.equals("prompt")&&item.project.equals(name))snapshot.add(parse(item.json()));work(()->{File temporary=File.createTempFile("project-",".txt",getCacheDir());try{try(Writer writer=new BufferedWriter(new OutputStreamWriter(new FileOutputStream(temporary),StandardCharsets.UTF_8))){writeProject(writer,name,snapshot);}try(InputStream in=new FileInputStream(temporary);OutputStream out=getContentResolver().openOutputStream(destination,"wt")){if(out==null)throw new IOException("Zieldatei nicht beschreibbar");byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}runOnUiThread(()->toast("Projekt als TXT exportiert"));}finally{temporary.delete();}});}catch(Exception e){error(e);}}
 void writeProject(Writer writer,String name,ArrayList<Item> entries)throws Exception{
 writer.write("# Promptwerk-Projekt: "+name+"\n\nNUTZUNGSHINWEIS: Nur für diese aktuelle Aufgabe verwenden. Nicht als dauerhafte Erinnerung oder Profilwissen übernehmen. Dieser Hinweis ersetzt keine Datenschutzeinstellungen des KI-Anbieters.\n\nARBEITSAUFTRAG AN DIE KI: Arbeite die folgenden aktiven Prompts in der angegebenen Reihenfolge ab. Berücksichtige den Zusammenhang des gesamten Projekts. Beachte die Anforderungen jedes Prompts, kennzeichne offene Punkte und fasse zum Abschluss die Ergebnisse je Auftrag zusammen.\n\nDie folgenden Abschnitte sind die Arbeitsaufträge dieses Projekts. Dateidaten sind gesondert markiert. TXT-Anhänge sind lesbarer Text; Bilder/PDF sind verlustfrei Base64-kodiert und müssen gegebenenfalls separat als Datei an die KI übergeben werden.\n");
 int number=0;for(Item item:entries){if(item.archived||!item.type.equals("prompt")||!item.project.equals(name))continue;writer.write("\n## "+(++number)+". "+item.title+"\nTyp: "+(item.type.equals("block")?"Baustein":"Prompt")+"\nStatus: "+(item.archived?"Erledigt":"Aktiv")+"\n\n"+item.text+"\n");for(Att attachment:item.files){File source=file(attachment);if(!source.isFile()||source.length()!=attachment.size||!digest(source).equals(attachment.key))throw new IOException("Anhang fehlt oder ist beschädigt: "+attachment.name);writer.write("\n### Anhang: "+attachment.name+"\nMIME: "+attachment.mime+"\nSHA-256: "+attachment.key+"\nBytes: "+attachment.size+"\n");if(attachment.mime.equals("text/plain")){writer.write("BEGIN TXT-ANHANG\n");try(Reader reader=new InputStreamReader(new FileInputStream(source),StandardCharsets.UTF_8)){char[] buffer=new char[8192];int n;while((n=reader.read(buffer))!=-1)writer.write(buffer,0,n);}writer.write("\nEND TXT-ANHANG\n");}else{writer.write("BEGIN BASE64\n");try(InputStream in=new FileInputStream(source)){byte[] buffer=new byte[3*4096];int n;while((n=in.read(buffer))!=-1){int used=n;while(used<buffer.length){int more=in.read(buffer,used,buffer.length-used);if(more<0)break;used+=more;}writer.write(android.util.Base64.encodeToString(buffer,0,used,android.util.Base64.NO_WRAP));}}writer.write("\nEND BASE64\n");}}}writer.flush();}

 void attachments(ArrayList<Att> target,Runnable changed){if(busy)return;String[] labels=new String[target.size()+1];labels[0]="+ Bilder / PDF / TXT hinzufügen";for(int j=0;j<target.size();j++){Att a=target.get(j);labels[j+1]=(a.sync?"☁ Drive · ":"▣ Lokal · ")+a.name+"  ("+((a.size+1023)/1024)+" KB)";}new AlertDialog.Builder(this).setTitle("Anhänge · "+target.size()).setItems(labels,(d,w)->{if(w==0){pickTarget=target;afterPick=changed;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","application/pdf","text/plain"});i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,20);}else{Att a=target.get(w-1);new AlertDialog.Builder(this).setTitle(a.name).setItems(new String[]{"Öffnen","Aus diesem Eintrag entfernen","In Zwischenablage kopieren",a.sync?"Nur auf diesem Gerät behalten":"Mit meinem Drive synchronisieren"},(x,y)->{if(y==3){if(!a.sync&&a.size>10485760){toast("Driveanlagen dürfen höchstens 10 MiB groß sein");return;}Att changedAtt=new Att(a.key,a.name,a.mime,a.size);changedAtt.sync=!a.sync;target.set(w-1,changedAtt);changed.run();toast(changedAtt.sync?"Für dein Drive ausgewählt · Eintrag speichern":"Dateiverweis bleibt lokal · Eintrag speichern");return;}if(y==2){copyAttachment(a);return;}if(y==1){target.remove(a);changed.run();}else try{Intent view=new Intent(Intent.ACTION_VIEW);view.setDataAndType(uri(a),a.mime);view.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(view);}catch(Exception e){error(new IOException("Keine passende Anzeige-App gefunden oder Datei fehlt."));}}).show();}}).setNegativeButton("Fertig",null).show();}
 Att importFile(android.net.Uri u)throws Exception{String name="Datei",mime=getContentResolver().getType(u);try(android.database.Cursor c=getContentResolver().query(u,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst()&&!c.isNull(0))name=c.getString(0);}if(name.length()>250)name=name.substring(name.length()-250);String low=name.toLowerCase(Locale.ROOT);if(mime==null||mime.equals("application/octet-stream")){if(low.endsWith(".pdf"))mime="application/pdf";else if(low.endsWith(".txt"))mime="text/plain";else {String ext=low.contains(".")?low.substring(low.lastIndexOf('.')+1):"";mime=android.webkit.MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext);}}if(!AttachmentPolicy.allowed(mime))throw new IOException("Nicht unterstützte Datei: "+name+". Bitte Bilder, PDF oder TXT wählen.");File tmp=File.createTempFile("attachment-",".tmp",getCacheDir());try{try(InputStream in=getContentResolver().openInputStream(u);OutputStream out=new FileOutputStream(tmp)){if(in==null)throw new IOException("Datei nicht lesbar");AttachmentPolicy.copy(in,out,AttachmentPolicy.FILE_LIMIT);}Att a=new Att(digest(tmp),name,mime,tmp.length());File dest=file(a);dest.getParentFile().mkdirs();if(!dest.exists()&&!tmp.renameTo(dest))throw new IOException("Datei konnte nicht gespeichert werden");return a;}finally{tmp.delete();}}
 void buildBackup(File tmp,JSONObject manifest,ArrayList<Att> all)throws Exception{try(java.util.zip.ZipOutputStream z=new java.util.zip.ZipOutputStream(new FileOutputStream(tmp))){z.putNextEntry(new java.util.zip.ZipEntry("promptwerk.json"));z.write(manifest.toString(2).getBytes(StandardCharsets.UTF_8));z.closeEntry();HashSet<String> seen=new HashSet<>();long total=0;for(Att a:all){if(!seen.add(a.key))continue;File f=file(a);if(!f.isFile()||f.length()!=a.size)throw new IOException("Anhang fehlt: "+a.name);total+=a.size;if(total>500L*1024*1024)throw new IOException("Sicherung über 500 MB. Bitte Sammlung verkleinern.");z.putNextEntry(new java.util.zip.ZipEntry("attachments/"+a.key));try(InputStream in=new FileInputStream(f)){AttachmentPolicy.copy(in,z,AttachmentPolicy.FILE_LIMIT);}z.closeEntry();}}}
 void exportBackup(android.net.Uri u,JSONObject manifest,ArrayList<Att> all)throws Exception{File tmp=File.createTempFile("backup-",".zip",getCacheDir());try{buildBackup(tmp,manifest,all);try(InputStream in=new FileInputStream(tmp);OutputStream out=getContentResolver().openOutputStream(u,"wt")){if(out==null)throw new IOException("Zieldatei nicht beschreibbar");AttachmentPolicy.copy(in,out,550L*1024*1024);}runOnUiThread(()->toast("Sicherung einschließlich Anhängen exportiert"));}finally{tmp.delete();}}
 void deleteTree(File f){File[] children=f.listFiles();if(children!=null)for(File c:children)deleteTree(c);f.delete();}
 void restoreExtras(JSONObject manifest){try{JSONObject current=new JSONObject(prefs.getString(ideasKey(),"{}")), restored=manifest.optJSONObject("ideas");if(restored!=null){Iterator<String> keys=restored.keys();while(keys.hasNext()){String key=keys.next();String value=restored.getString(key);if(current.has(key)&&!current.getString(key).equals(value))key=key+" (Import "+System.currentTimeMillis()+")";current.put(key,value);}}JSONArray parked=new JSONArray(prefs.getString(parkedKey(),"[]")), next=manifest.optJSONArray("parkedDrafts");if(next!=null)for(int n=0;n<next.length();n++)parked.put(next.getJSONObject(n));prefs.edit().putString(ideasKey(),current.toString()).putString(parkedKey(),parked.toString()).commit();}catch(Exception e){error(e);}}
 void checkFiles(java.util.List<Att> files,File stage)throws Exception{for(Att a:files){File f=new File(stage,a.key);if(!f.isFile()&&file(a).isFile())f=file(a);if(!f.isFile()||f.length()!=a.size||!digest(f).equals(a.key))throw new IOException("Fehlender oder beschädigter Anhang: "+a.name);}}
 void importBackup(android.net.Uri u)throws Exception{File stage=new File(getCacheDir(),"restore-"+UUID.randomUUID());stage.mkdirs();boolean handed=false;try{JSONObject manifest;try(java.io.BufferedInputStream in=new java.io.BufferedInputStream(getContentResolver().openInputStream(u))){in.mark(4);int first=in.read(),second=in.read();in.reset();if(first=='P'&&second=='K'){byte[] metadata=null;HashSet<String> names=new HashSet<>();long total=0;try(java.util.zip.ZipInputStream z=new java.util.zip.ZipInputStream(in)){java.util.zip.ZipEntry e;int entries=0;while((e=z.getNextEntry())!=null){if(++entries>20000)throw new IOException("Zu viele Dateien");String n=e.getName();if(!names.add(n))throw new IOException("Doppelter ZIP-Eintrag");if(n.equals("promptwerk.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();AttachmentPolicy.copy(z,out,10L*1024*1024);metadata=out.toByteArray();}else if(n.startsWith("attachments/")&&AttachmentPolicy.validKey(n.substring(12))){File f=new File(stage,n.substring(12));try(OutputStream out=new FileOutputStream(f)){total+=AttachmentPolicy.copy(z,out,AttachmentPolicy.FILE_LIMIT);}if(total>500L*1024*1024)throw new IOException("Sicherung größer als 500 MB");}else throw new IOException("Unbekannter oder unsicherer ZIP-Pfad");z.closeEntry();}}if(metadata==null)throw new IOException("Sicherungsbeschreibung fehlt");manifest=new JSONObject(new String(metadata,StandardCharsets.UTF_8));}else{ByteArrayOutputStream out=new ByteArrayOutputStream();AttachmentPolicy.copy(in,out,10L*1024*1024);manifest=new JSONObject(out.toString("UTF-8"));}}
 int version=manifest.optInt("version");if(!manifest.optString("format").equals("promptwerk")||(version!=1&&version!=2&&version!=3))throw new IOException("Keine unterstützte Promptwerk-Sicherung");JSONArray array=manifest.getJSONArray("items");if(array.length()>10000)throw new IOException("Zu viele Einträge");ArrayList<Item> incoming=new ArrayList<>();for(int j=0;j<array.length();j++){Item it=parse(array.getJSONObject(j));checkFiles(it.files,stage);incoming.add(it);}String draft=manifest.optString("draft","");if(draft.length()>1000000)throw new IOException("Entwurf zu groß");ArrayList<Att> restored=readAtt(manifest.optJSONArray("draftFiles"));checkFiles(restored,stage);JSONArray parked=manifest.optJSONArray("parkedDrafts");if(parked!=null)for(int n=0;n<parked.length();n++){JSONObject parkedDraft=parked.getJSONObject(n);if(parkedDraft.getString("text").length()>200000)throw new IOException("Geparkter Entwurf zu groß");checkFiles(readAtt(parkedDraft.optJSONArray("files")),stage);}JSONObject ideas=manifest.optJSONObject("ideas");if(ideas!=null){Iterator<String> keys=ideas.keys();while(keys.hasNext())if(ideas.getString(keys.next()).length()>200000)throw new IOException("Ideennotiz zu groß");}
 runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Sicherung importieren?").setMessage(incoming.size()+" Einträge geprüft, einschließlich Anhängen. Bestehende Einträge bleiben erhalten; identische Inhalte werden übersprungen. Gleiche Namen erfordern zwei Bestätigungen zum Überschreiben; Abbrechen beendet die restliche Eintragsübernahme.").setNegativeButton("Abbrechen",(d,w)->deleteTree(stage)).setOnCancelListener(d->deleteTree(stage)).setPositiveButton("Importieren",(d,w)->work(()->{try{ArrayList<Att> all=new ArrayList<>(restored);if(parked!=null)for(int n=0;n<parked.length();n++)all.addAll(readAtt(parked.getJSONObject(n).optJSONArray("files")));for(Item it:incoming)all.addAll(it.files);for(Att a:all){File src=new File(stage,a.key),dest=file(a);if(src.isFile()&&!dest.exists()){dest.getParentFile().mkdirs();if(!src.renameTo(dest))throw new IOException("Anhang konnte nicht übernommen werden");}}runOnUiThread(()->{try{mergeImport(incoming,()->{restoreExtras(manifest);if(!draft.isEmpty()||!restored.isEmpty())new AlertDialog.Builder(this).setTitle("Gesicherten Entwurf übernehmen?").setMessage("Ersetzt Text und Anhänge des aktuellen Entwurfs. ↶ holt den bisherigen Entwurf zurück.").setNegativeButton("Behalten",null).setPositiveButton("Übernehmen",(x,y)->{last=editor.getText().toString();lastFiles=new ArrayList<>(draftFiles);setHandedOver(false);restoring=true;editor.setText(draft);draftFiles=new ArrayList<>(restored);restoring=false;draftChanged();}).show();});}catch(Exception e){error(e);}});}finally{deleteTree(stage);}})).show());handed=true;
 }finally{if(!handed)deleteTree(stage);}}

